class _DailyRewardScreenState extends State<DailyRewardScreen>{final store=GameStore.instance;static const rewards=[200,300,450,600,800,1000,2000];@override void initState(){super.initState();store.addListener(_r);}@override void dispose(){store.removeListener(_r);super.dispose();}void _r(){if(mounted)setState((){});} @override Widget build(BuildContext context){final current=store.dailyStreak==0?0:(store.dailyStreak-1)%7;return Scaffold(appBar:AppBar(title:const Text('DAILY REWARD'),actions:[Padding(padding:const EdgeInsets.only(right:12),child:CoinBadge(coins:store.coins))]),body:Padding(padding:const EdgeInsets.all(18),child:Column(children:[const Text('COME BACK EVERY DAY',style:TextStyle(fontSize:24,fontWeight:FontWeight.w900)),const SizedBox(height:8),const Text('A 7-day reward cycle. Missing a day restarts the streak.',textAlign:TextAlign.center,style:TextStyle(color:Colors.white60)),const SizedBox(height:24),Expanded(child:GridView.builder(gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,childAspectRatio:1.35,crossAxisSpacing:12,mainAxisSpacing:12),itemCount:7,itemBuilder:(_,i){final claimedToday=!store.canClaimDaily&&i==current;return NeonCard(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text('DAY ${i+1}',style:TextStyle(fontWeight:FontWeight.w900,color:i==6?const Color(0xFFFBBF24):Colors.white)),const SizedBox(height:6),Image.asset('assets/images/ui/coin.png',width:30),Text('${rewards[i]}',style:const TextStyle(fontSize:19,fontWeight:FontWeight.w900)),if(claimedToday)const Text('CLAIMED',style:TextStyle(color:Colors.greenAccent,fontSize:10,fontWeight:FontWeight.bold))]));})),GradientButton(label:store.canClaimDaily?'CLAIM ${store.nextDailyReward} COINS':'COME BACK TOMORROW',onPressed:store.canClaimDaily?()async{final r=await store.claimDaily();if(r>0){await AudioService.instance.play('reward.wav');}}:null)])));}}
